impl TempDir { fn remove_dir (path : & Path) -> Result < () , std :: io :: Error > { match std :: fs :: remove_dir_all (path) { Ok (()) => Ok (()) , Err (e) if e . kind () == ErrorKind :: NotFound => Ok (()) , Err (e) => Err (std :: io :: Error :: new (e . kind () , format ! ("error removing directory and contents {path:?}: {e}") ,)) , } } # [doc = " Create a new empty directory in a system temporary directory."] # [doc = ""] # [doc = " Drop the struct to delete the directory and everything under it."] # [doc = " Deletes symbolic links and does not follow them."] # [doc = ""] # [doc = " Ignores any error while deleting."] # [doc = " See [`TempDir::panic_on_cleanup_error`](struct.TempDir.html#method.panic_on_cleanup_error)."] # [doc = ""] # [doc = " # Errors"] # [doc = " Returns `Err` when it fails to create the directory."] # [doc = ""] # [doc = " # Example"] # [doc = " ```rust"] # [doc = " // Prints \"/tmp/t1a9b-0\"."] # [doc = " println!(\"{:?}\", temp_dir::TempDir::new().unwrap().path());"] # [doc = " ```"] pub fn new () -> Result < Self , std :: io :: Error > { Self :: with_prefix ("t") } # [doc = " Create a new empty directory in a system temporary directory."] # [doc = " Use `prefix` as the first part of the directory's name."] # [doc = ""] # [doc = " Drop the struct to delete the directory and everything under it."] # [doc = " Deletes symbolic links and does not follow them."] # [doc = ""] # [doc = " Ignores any error while deleting."] # [doc = " See [`TempDir::panic_on_cleanup_error`](struct.TempDir.html#method.panic_on_cleanup_error)."] # [doc = ""] # [doc = " # Errors"] # [doc = " Returns `Err` when it fails to create the directory."] # [doc = ""] # [doc = " # Example"] # [doc = " ```rust"] # [doc = " // Prints \"/tmp/ok1a9b-0\"."] # [doc = " println!(\"{:?}\", temp_dir::TempDir::with_prefix(\"ok\").unwrap().path());"] # [doc = " ```"] pub fn with_prefix (prefix : impl AsRef < str >) -> Result < Self , std :: io :: Error > { loop { let path_buf = std :: env :: temp_dir () . join (format ! ("{}{:x}-{:x}" , prefix . as_ref () , std :: process :: id () , INTERNAL_COUNTER . fetch_add (1 , Ordering :: AcqRel) ,)) ; match std :: fs :: create_dir (& path_buf) { Err (e) if e . kind () == ErrorKind :: AlreadyExists && INTERNAL_RETRY . load (Ordering :: Acquire) => { } Err (e) => { return Err (std :: io :: Error :: new (e . kind () , format ! ("error creating directory {path_buf:?}: {e}") ,)) ; } Ok (()) => { return Ok (Self { delete_on_drop : true , panic_on_delete_err : false , path_buf , }) ; } } } } # [doc = " Remove the directory and its contents now."] # [doc = ""] # [doc = " # Errors"] # [doc = " Returns an error if the directory exists and we fail to remove it and its contents."] # [allow (clippy :: missing_panics_doc)] pub fn cleanup (self) -> Result < () , std :: io :: Error > { Self :: remove_dir (& self . path_buf) } # [doc = " Make the struct panic on drop if it hits an error while"] # [doc = " removing the directory or its contents."] # [must_use] pub fn panic_on_cleanup_error (mut self) -> Self { self . panic_on_delete_err = true ; self } # [doc = " Do not delete the directory or its contents."] # [doc = ""] # [doc = " This is useful when debugging a test."] pub fn leak (mut self) { self . delete_on_drop = false ; } # [doc = " Do not delete the directory or its contents on Drop."] # [must_use] pub fn dont_delete_on_drop (mut self) -> Self { self . delete_on_drop = false ; self } # [doc = " The path to the directory."] # [must_use] # [allow (clippy :: missing_panics_doc)] pub fn path (& self) -> & Path { & self . path_buf } # [doc = " The path to `name` under the directory."] # [must_use] # [allow (clippy :: missing_panics_doc)] pub fn child (& self , name : impl AsRef < str >) -> PathBuf { let mut result = self . path_buf . clone () ; result . push (name . as_ref ()) ; result } }